<script setup lang="ts">import {watch,nextTick,ref} from 'vue';const p=withDefaults(defineProps<{open:boolean;title:string;side?:'left'|'right'}>(),{side:'right'});const emit=defineEmits<{close:[]}>();const panel=ref<HTMLElement|null>(null);let previous:Element|null=null;watch(()=>p.open,async open=>{if(open){previous=document.activeElement;await nextTick();panel.value?.focus()}else if(previous instanceof HTMLElement)previous.focus()});function key(e:KeyboardEvent){if(e.key==='Escape')emit('close');if(e.key==='Tab'&&panel.value){const els=Array.from(panel.value.querySelectorAll<HTMLElement>('button,a[href],input,select,textarea,[tabindex]:not([tabindex="-1"])')).filter(el=>!el.hasAttribute('disabled'));if(!els.length){e.preventDefault();return}const first=els[0],last=els[els.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}}</script><template><Teleport to="body"><div v-if="open" class="vx-overlay" @keydown="key"><div class="vx-overlay__backdrop" @click="emit('close')"/><aside ref="panel" tabindex="-1" class="vx-drawer" :data-side="side" role="dialog" aria-modal="true" :aria-label="title"><header><h2>{{title}}</h2><button aria-label="Close" @click="emit('close')">×</button></header><div class="vx-drawer__body"><slot/></div><footer v-if="$slots.footer"><slot name="footer"/></footer></aside></div></Teleport></template>